package com.dummyhelper;

import net.runelite.api.GameObject;
import net.runelite.api.Point;
import net.runelite.api.Perspective;
import net.runelite.api.coords.LocalPoint;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.OverlayUtil;

import javax.inject.Inject;
import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.Graphics2D;
import java.awt.Shape;

/**
 * Draws a highlight box around the active dummy and shows the required style as text above it.
 */
public class DummyHelperOverlay extends Overlay
{
	private final DummyHelperPlugin plugin;
	private final DummyHelperConfig config;

	@Inject
	public DummyHelperOverlay(DummyHelperPlugin plugin, DummyHelperConfig config)
	{
		super(plugin);
		this.plugin = plugin;
		this.config = config;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_SCENE);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!config.showOverlay() || !plugin.isInWarriorsGuild())
		{
			return null;
		}

		GameObject dummy = plugin.getActiveDummy();
		String style = plugin.getRequiredStyle();

		if (dummy == null || style == null)
		{
			return null;
		}

		// Draw box around the dummy
		Shape hull = dummy.getConvexHull();
		if (hull != null)
		{
			Color highlightColor = config.correctColor();
			graphics.setColor(highlightColor);
			graphics.setStroke(new BasicStroke(3));
			graphics.draw(hull);

			// Semi-transparent fill
			graphics.setColor(new Color(
				highlightColor.getRed(),
				highlightColor.getGreen(),
				highlightColor.getBlue(),
				50
			));
			graphics.fill(hull);
		}

		// Draw style text above the dummy
		LocalPoint localPoint = dummy.getLocalLocation();
		if (localPoint != null)
		{
			String text = "Use: " + style;
			Point textPoint = Perspective.getCanvasTextLocation(
				plugin.getClient(), graphics, localPoint, text, 150
			);

			if (textPoint != null)
			{
				Font original = graphics.getFont();
				graphics.setFont(original.deriveFont(Font.BOLD, 16f));
				OverlayUtil.renderTextLocation(graphics, textPoint, text, Color.WHITE);
				graphics.setFont(original);
			}
		}

		return null;
	}
}

package com.dummyhelper;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;

import java.awt.Color;

@ConfigGroup("dummyhelper")
public interface DummyHelperConfig extends Config
{
	@ConfigItem(
		keyName = "showOverlay",
		name = "Show Overlay",
		description = "Display the dummy helper overlay panel",
		position = 1
	)
	default boolean showOverlay()
	{
		return true;
	}

	@ConfigItem(
		keyName = "correctColor",
		name = "Correct Style Color",
		description = "Color shown when your attack style matches the dummy",
		position = 2
	)
	default Color correctColor()
	{
		return Color.GREEN;
	}

	@ConfigItem(
		keyName = "incorrectColor",
		name = "Incorrect Style Color",
		description = "Color shown when your attack style does not match the dummy",
		position = 3
	)
	default Color incorrectColor()
	{
		return Color.RED;
	}
}

package com.dummyhelper;

import net.runelite.api.widgets.Widget;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

import javax.inject.Inject;
import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Rectangle;

/**
 * Draws a colored highlight over the correct combat style button
 * in the combat options tab (widget group 593).
 */
public class CombatStyleOverlay extends Overlay
{
	private final DummyHelperPlugin plugin;
	private final DummyHelperConfig config;

	@Inject
	public CombatStyleOverlay(DummyHelperPlugin plugin, DummyHelperConfig config)
	{
		super(plugin);
		this.plugin = plugin;
		this.config = config;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!config.showOverlay() || !plugin.isInWarriorsGuild())
		{
			return null;
		}

		int index = plugin.getHighlightButtonIndex();
		if (index < 0)
		{
			return null;
		}

		Widget widget = plugin.getStyleWidget(index);
		if (widget == null || widget.isHidden())
		{
			return null;
		}

		Rectangle bounds = widget.getBounds();
		if (bounds == null || bounds.width == 0)
		{
			return null;
		}

		Color color = config.correctColor();

		// Semi-transparent fill
		graphics.setColor(new Color(color.getRed(), color.getGreen(), color.getBlue(), 60));
		graphics.fill(bounds);

		// Border
		graphics.setColor(color);
		graphics.setStroke(new BasicStroke(2));
		graphics.draw(bounds);

		return null;
	}
}

package com.dummyhelper;

import java.util.HashMap;
import java.util.Map;

/**
 * Maps weapon category (from VarbitID.COMBAT_WEAPON_CATEGORY) to the
 * attack type (Stab/Slash/Crush) each of the 4 style buttons produces.
 *
 * Source: https://oldschool.runescape.wiki/w/Weapons/Types
 */
public class WeaponAttackTypes
{
	/**
	 * Map of weaponCategory -> String[4] of attack types per button index.
	 * null means that button doesn't exist for this weapon.
	 */
	private static final Map<Integer, String[]> CATEGORY_ATTACK_TYPES = new HashMap<>();

	static
	{
		// Category IDs from VarbitID.COMBAT_WEAPON_CATEGORY
		// Values sourced from OSRS wiki Weapons/Types page

		// 0: Unarmed
		CATEGORY_ATTACK_TYPES.put(0, new String[]{"Crush", "Crush", "Crush", null});
		// 1: Axe
		CATEGORY_ATTACK_TYPES.put(1, new String[]{"Slash", "Slash", "Crush", "Slash"});
		// 2: Blunt (mace-like, 3 styles)
		CATEGORY_ATTACK_TYPES.put(2, new String[]{"Crush", "Crush", "Crush", null});
		// 3: Bow
		CATEGORY_ATTACK_TYPES.put(3, new String[]{null, null, null, null});
		// 4: Claws
		CATEGORY_ATTACK_TYPES.put(4, new String[]{"Slash", "Slash", "Stab", "Slash"});
		// 5: Crossbow
		CATEGORY_ATTACK_TYPES.put(5, new String[]{null, null, null, null});
		// 6: Salamander
		CATEGORY_ATTACK_TYPES.put(6, new String[]{null, null, null, null});
		// 7: Chinchompa
		CATEGORY_ATTACK_TYPES.put(7, new String[]{null, null, null, null});
		// 8: Gun (hand cannon)
		CATEGORY_ATTACK_TYPES.put(8, new String[]{null, null, null, null});
		// 9: Slash Sword (longsword, scimitar)
		CATEGORY_ATTACK_TYPES.put(9, new String[]{"Slash", "Slash", "Stab", "Slash"});
		// 10: 2h Sword
		CATEGORY_ATTACK_TYPES.put(10, new String[]{"Slash", "Slash", "Crush", "Slash"});
		// 11: Pickaxe
		CATEGORY_ATTACK_TYPES.put(11, new String[]{"Stab", "Stab", "Crush", "Stab"});
		// 12: Polearm (halberd)
		CATEGORY_ATTACK_TYPES.put(12, new String[]{"Stab", "Slash", "Stab", null});
		// 13: Polestaff
		CATEGORY_ATTACK_TYPES.put(13, new String[]{"Crush", "Crush", "Crush", null});
		// 14: Scythe
		CATEGORY_ATTACK_TYPES.put(14, new String[]{"Slash", "Slash", "Crush", "Slash"});
		// 15: Spear
		CATEGORY_ATTACK_TYPES.put(15, new String[]{"Stab", "Slash", "Crush", "Stab"});
		// 16: Spiked (mace with spike)
		CATEGORY_ATTACK_TYPES.put(16, new String[]{"Crush", "Crush", "Stab", "Crush"});
		// 17: Stab Sword (dagger, rapier)
		CATEGORY_ATTACK_TYPES.put(17, new String[]{"Stab", "Stab", "Slash", "Stab"});
		// 18: Staff (magic staff)
		CATEGORY_ATTACK_TYPES.put(18, new String[]{"Crush", "Crush", "Crush", null});
		// 19: Thrown (darts, knives)
		CATEGORY_ATTACK_TYPES.put(19, new String[]{null, null, null, null});
		// 20: Whip
		CATEGORY_ATTACK_TYPES.put(20, new String[]{"Slash", "Slash", "Slash", null});
		// 21: Banner
		CATEGORY_ATTACK_TYPES.put(21, new String[]{"Stab", "Slash", "Crush", "Stab"});
		// 22: Bludgeon
		CATEGORY_ATTACK_TYPES.put(22, new String[]{"Crush", "Crush", "Crush", null});
		// 23: Bulwark
		CATEGORY_ATTACK_TYPES.put(23, new String[]{"Crush", null, null, null});
		// 24: Partisan
		CATEGORY_ATTACK_TYPES.put(24, new String[]{"Stab", "Stab", "Crush", "Stab"});
	}

	/**
	 * Get the attack type for a given weapon category and style button index.
	 *
	 * @param weaponCategory from VarbitID.COMBAT_WEAPON_CATEGORY
	 * @param buttonIndex 0-3 for the 4 style buttons
	 * @return "Stab", "Slash", "Crush", or null if unknown
	 */
	public static String getAttackType(int weaponCategory, int buttonIndex)
	{
		String[] types = CATEGORY_ATTACK_TYPES.get(weaponCategory);
		if (types == null || buttonIndex < 0 || buttonIndex >= types.length)
		{
			return null;
		}
		return types[buttonIndex];
	}
}

package com.dummyhelper;

import com.google.inject.Provides;
import lombok.AccessLevel;
import lombok.Getter;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Animation;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.DynamicObject;
import net.runelite.api.GameObject;
import net.runelite.api.Varbits;

import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.GameObjectDespawned;
import net.runelite.api.events.GameObjectSpawned;
import net.runelite.api.events.GameTick;
import net.runelite.api.widgets.Widget;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;

import javax.inject.Inject;
import java.util.Arrays;
import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;

@Slf4j
@PluginDescriptor(
	name = "Warriors Guild Dummy Helper",
	description = "Highlights the correct attack style for the active dummy in the Warriors Guild",
	tags = {"warriors", "guild", "dummy", "combat", "attack", "style", "defender"}
)
public class DummyHelperPlugin extends Plugin
{
	/**
	 * Dummy object ID -> required style/attack type.
	 * IDs from the Warriors Guild basement dummy room.
	 * Values are either a combat style name (Accurate, Aggressive, Controlled, Defensive)
	 * or an attack type (Stab, Slash, Crush).
	 */
	static final Map<Integer, String> DUMMY_STYLES = new HashMap<>();

	static
	{
		DUMMY_STYLES.put(23958, "Accurate");
		DUMMY_STYLES.put(23959, "Slash");
		DUMMY_STYLES.put(23960, "Aggressive");
		DUMMY_STYLES.put(23961, "Controlled");
		DUMMY_STYLES.put(23962, "Crush");
		DUMMY_STYLES.put(23963, "Stab");
		DUMMY_STYLES.put(23964, "Defensive");
	}

	/**
	 * The 4 combat style names in VarPlayer 43 (COMBAT_STYLE) order.
	 * Used for direct index lookup when a dummy requires a combat style.
	 */
	private static final String[] STYLE_NAMES = {"Accurate", "Aggressive", "Controlled", "Defensive"};

	// Warriors Guild map region IDs (basement + ground floor)
	private static final int WARRIORS_GUILD_REGION_1 = 11575;
	private static final int WARRIORS_GUILD_REGION_2 = 11319;

	/**
	 * Combat options widget group (593) and the 4 style button children.
	 * Children 8/12/16/20 are the clickable style containers;
	 * child 4 is the combat level display (not a button).
	 */
	static final int COMBAT_GROUP_ID = 593;
	static final int[] STYLE_CHILDREN = {8, 12, 16, 20};

	@Getter(AccessLevel.PACKAGE)
	@Inject
	private Client client;

	@Inject
	private DummyHelperConfig config;

	@Inject
	private DummyHelperOverlay dummyOverlay;

	@Inject
	private CombatStyleOverlay combatOverlay;

	@Inject
	private OverlayManager overlayManager;

	private final Set<GameObject> trackedDummies = new HashSet<>();

	@Getter(AccessLevel.PACKAGE)
	private String requiredStyle = null;

	@Getter(AccessLevel.PACKAGE)
	private GameObject activeDummy = null;

	@Getter(AccessLevel.PACKAGE)
	private boolean inWarriorsGuild = false;

	@Getter(AccessLevel.PACKAGE)
	private int highlightButtonIndex = -1;

	// Ticks since the active dummy was last seen animating.
	// Gives a grace period before releasing the latch, since
	// animations can briefly return -1 between cycles.
	private static final int IDLE_GRACE_TICKS = 5;
	private int idleTickCount = 0;

	@Override
	protected void startUp()
	{
		overlayManager.add(dummyOverlay);
		overlayManager.add(combatOverlay);
	}

	@Override
	protected void shutDown()
	{
		overlayManager.remove(dummyOverlay);
		overlayManager.remove(combatOverlay);
		trackedDummies.clear();
		reset();
	}

	private void reset()
	{
		requiredStyle = null;
		activeDummy = null;
		highlightButtonIndex = -1;
		idleTickCount = 0;
	}

	@Provides
	DummyHelperConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(DummyHelperConfig.class);
	}

	@Subscribe
	public void onGameObjectSpawned(GameObjectSpawned event)
	{
		GameObject obj = event.getGameObject();
		if (DUMMY_STYLES.containsKey(obj.getId()))
		{
			trackedDummies.add(obj);
		}
	}

	@Subscribe
	public void onGameObjectDespawned(GameObjectDespawned event)
	{
		GameObject obj = event.getGameObject();
		trackedDummies.remove(obj);
		if (obj.equals(activeDummy))
		{
			reset();
		}
	}

	@Subscribe
	public void onChatMessage(ChatMessage event)
	{
		if (!inWarriorsGuild)
		{
			return;
		}

		ChatMessageType type = event.getType();
		if (type != ChatMessageType.SPAM && type != ChatMessageType.GAMEMESSAGE)
		{
			return;
		}

		String msg = event.getMessage().toLowerCase();

		// Successful hit — clear and wait for next dummy
		if (msg.contains("token") || msg.contains("you hit the dummy correctly"))
		{
			reset();
		}
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		inWarriorsGuild = checkInWarriorsGuild();

		if (!inWarriorsGuild)
		{
			reset();
			return;
		}

		// If we have a latched dummy, verify it's still animating.
		// Allow a grace period since animations can briefly return -1 between cycles.
		if (activeDummy != null)
		{
			if (isDummyAnimating(activeDummy))
			{
				idleTickCount = 0;
			}
			else
			{
				idleTickCount++;
				if (idleTickCount >= IDLE_GRACE_TICKS)
				{
					reset();
				}
			}
		}

		if (requiredStyle == null)
		{
			scanForActiveDummy();
		}

		if (requiredStyle != null)
		{
			highlightButtonIndex = findMatchingButton(requiredStyle);
		}
	}

	private boolean isDummyAnimating(GameObject dummy)
	{
		if (!(dummy.getRenderable() instanceof DynamicObject))
		{
			return false;
		}

		DynamicObject dynObj = (DynamicObject) dummy.getRenderable();
		Animation anim = dynObj.getAnimation();
		return anim != null && anim.getId() != -1;
	}

	private void scanForActiveDummy()
	{
		for (GameObject dummy : trackedDummies)
		{
			if (isDummyAnimating(dummy))
			{
				String style = DUMMY_STYLES.get(dummy.getId());
				if (style != null)
				{
					requiredStyle = style;
					activeDummy = dummy;
					log.debug("Dummy active: {} (ID {})", style, dummy.getId());
					return;
				}
			}
		}
	}

	/**
	 * Find which button (0-3) to highlight for the required style.
	 *
	 * Combat styles (Accurate/Aggressive/Controlled/Defensive) map directly
	 * to button indices 0-3 since they follow VarPlayer 43 order.
	 *
	 * Attack types (Stab/Slash/Crush) require reading the equipped weapon
	 * category from Varbits.EQUIPPED_WEAPON_TYPE, then consulting the
	 * WeaponAttackTypes table to find which button produces the needed type.
	 */
	private int findMatchingButton(String required)
	{
		// Combat styles map directly to button indices
		for (int i = 0; i < STYLE_NAMES.length; i++)
		{
			if (STYLE_NAMES[i].equalsIgnoreCase(required))
			{
				// Verify the button widget exists
				Widget w = client.getWidget(COMBAT_GROUP_ID, STYLE_CHILDREN[i]);
				if (w != null && !w.isHidden())
				{
					return i;
				}
				return -1;
			}
		}

		// Attack types (Stab/Slash/Crush) — use weapon category table
		int weaponCategory = client.getVarbitValue(Varbits.EQUIPPED_WEAPON_TYPE);

		for (int i = 0; i < STYLE_CHILDREN.length; i++)
		{
			Widget w = client.getWidget(COMBAT_GROUP_ID, STYLE_CHILDREN[i]);
			if (w == null || w.isHidden())
			{
				continue;
			}

			String attackType = WeaponAttackTypes.getAttackType(weaponCategory, i);
			if (attackType != null && attackType.equalsIgnoreCase(required))
			{
				return i;
			}
		}

		return -1;
	}

	Widget getStyleWidget(int index)
	{
		if (index < 0 || index >= STYLE_CHILDREN.length)
		{
			return null;
		}
		return client.getWidget(COMBAT_GROUP_ID, STYLE_CHILDREN[index]);
	}

	private boolean checkInWarriorsGuild()
	{
		if (client.getLocalPlayer() == null)
		{
			return false;
		}

		int[] regions = client.getMapRegions();
		if (regions == null)
		{
			return false;
		}

		return Arrays.stream(regions)
			.anyMatch(r -> r == WARRIORS_GUILD_REGION_1 || r == WARRIORS_GUILD_REGION_2);
	}
}
